per_call.cmd:
cat > /etc/nginx/sites-available/vnc <<'EOF'
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;

    location / {
        proxy_pass http://127.0.0.1:8080;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }
}
EOF
rm -f /etc/nginx/sites-enabled/default
ln -sf /etc/nginx/sites-available/vnc /etc/nginx/sites-enabled/vnc
nginx -t 2>&1

cat > /tmp/fdcheck.py << 'PYEOF'
import subprocess, os
qpid = subprocess.check_output(['pgrep', '-f', 'qemu-system-i386']).decode().strip().split('\n')[0]
print('QEMU pid:', qpid)
fds = os.listdir(f'/proc/{qpid}/fd')
for fd in sorted(fds, key=int):
    try:
        target = os.readlink(f'/proc/{qpid}/fd/{fd}')
        if 'socket' in target or '5901' in target or 'unix' in target:
            print(f'  fd {fd}: {target}')
    except:
        pass
print()
print('TCP on 5901:')
for line in open('/proc/net/tcp'):
    parts = line.split()
    if len(parts) > 3:
        port = int(parts[1].split(':')[1], 16)
        if port == 5901:
            print(f'  {parts[1]} state={parts[3]}')
PYEOF
python3 /tmp/fdcheck.py
